import sys

def sieve_of_eratosthenes(limit):
    """Generate all primes up to limit using Sieve of Eratosthenes"""
    if limit < 2:
        return []

    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(math.sqrt(limit)) + 1):
        if is_prime[i]:
            for j in range(i * i, limit + 1, i):
                is_prime[j] = False

    return [i for i in range(2, limit + 1) if is_prime[i]]

def get_primes_in_range(m, n):
    """Get all primes in the range [m, n] using precomputed primes up to n"""
    # Since n can be up to 10^9, we can't generate all primes up to n directly
    # Instead, we use the fact that n - m <= 100000, so we can use segmented sieve

    # First, generate primes up to sqrt(n)
    sqrt_n = int(math.sqrt(n)) + 1
    base_primes = sieve_of_eratosthenes(sqrt_n)

    # Use segmented sieve to find primes in [m, n]
    size = n - m + 1
    is_prime_segment = [True] * size

    # Mark multiples of each base prime in the segment [m, n]
    for prime in base_primes:
        # Find the first multiple of prime >= m
        start = max(prime * prime, (m + prime - 1) // prime * prime)

        # Mark all multiples of prime in [m, n]
        for j in range(start, n + 1, prime):
            is_prime_segment[j - m] = False

    # Collect all primes in the range
    result = []
    for i in range(m, n + 1):
        if is_prime_segment[i - m]:
            result.append(i)

    return result

